const root=document.querySelector('#manutencao-view');let rows=[],view='kanban';
const e=v=>String(v??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const sts=['Solicitado','Em cotação','Aguardando aprovação','Pedido emitido','Aguardando entrega','Recebido / Concluído','Cancelado','Duplicado'];
const lanes=[['Solicitado',['Solicitado']],['Em cotação',['Em cotação']],['Aguardando aprovação',['Aguardando aprovação']],['Pedido emitido',['Pedido emitido']],['Aguardando entrega',['Aguardando entrega']],['Concluído / Cancelado',['Recebido / Concluído','Cancelado','Duplicado']]];
const opt=(a,v)=>a.map(x=>'<option'+(x===v?' selected':'')+'>'+e(x)+'</option>').join('');
const closed=r=>['Recebido / Concluído','Cancelado','Duplicado'].includes(r.status);
const d=v=>v?v.split('-').reverse().join('/'):'—';
const meta=r=>{try{const a=JSON.parse(r.quotesJson||'[]');return a.find(x=>x&&x.kind==='commercial')||{}}catch{return {}}};
const money=v=>{const n=Number(String(v||'').replace(',','.'));return Number.isFinite(n)&&n?new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(n):'—'};
async function load(){const x=await fetch('/api/maintenance');rows=(await x.json()).requests||[];render()}
function card(r){return '<article class="maintenance-card '+(r.priority==='Urgente'?'urgent':'')+'" data-id="'+r.id+'"><div class="maintenance-card-head"><strong>'+e(r.number)+'</strong><select data-status="'+r.id+'">'+opt(sts,r.status)+'</select></div><h4>'+e(r.description)+'</h4><p><b>Solicitante:</b> '+e(r.requester)+'</p><p><b>Responsável:</b> '+e(r.buyer||'Não assumido')+'</p><p><b>Origem:</b> '+e(r.origin)+(r.oc?' · OC '+e(r.oc):'')+'</p><p><b>Necessário até:</b> '+d(r.neededDate)+'</p><p><b>Quantidade:</b> '+e(r.quantity||'—')+' '+e(r.unit||'')+'</p><p><b>Equipamento:</b> '+e(r.equipment||'—')+'</p><p><b>Fornecedor:</b> '+e(r.supplier||'—')+'</p><p><b>Valor:</b> '+money(meta(r).amount)+'</p><p><b>Pagamento:</b> '+e(meta(r).paymentTerms||'—')+'</p><p><b>Pedido:</b> '+e(r.systemOrder||'—')+'</p>'+(r.status==='Aguardando entrega'&&!r.promisedDate?'<p class="maintenance-alert">⚠ Prazo de entrega não informado</p>':'')+'</article>'}
function render(){const open=rows.filter(r=>!closed(r));root.innerHTML='<div class="maintenance-kpis"><div><strong>'+open.length+'</strong><span>Em aberto</span></div><div><strong>'+rows.filter(r=>r.status==='Em cotação').length+'</strong><span>Em cotação</span></div><div><strong>'+rows.filter(r=>r.status==='Aguardando aprovação').length+'</strong><span>Aguardando aprovação</span></div><div><strong>'+rows.filter(r=>r.status==='Pedido emitido').length+'</strong><span>Pedido emitido</span></div><div><strong>'+rows.filter(r=>r.status==='Aguardando entrega').length+'</strong><span>Aguardando entrega</span></div><div><strong>'+rows.filter(r=>r.priority==='Urgente'&&!closed(r)).length+'</strong><span>Urgentes</span></div></div><section class="panel maintenance-toolbar"><button id="mn">+ Nova solicitação</button><input id="ms" placeholder="Buscar material, serviço, OC, pedido, solicitante ou responsável"><select id="mstatus"><option value="">Todos os status</option>'+opt(sts,'')+'</select><select id="morigin"><option value="">Todas as origens</option>'+opt(['OC','WhatsApp','Outro'],'')+'</select><div class="maintenance-view"><button data-view="kanban">▦ Kanban</button><button data-view="list">☷ Lista</button></div></section><div id="me"></div><div id="maintenance-content"></div>';document.querySelector('#mn').onclick=()=>form({});document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;draw()});['ms','mstatus','morigin'].forEach(id=>document.querySelector('#'+id).oninput=draw);draw()}
function filtered(){const q=document.querySelector('#ms').value.toLowerCase(),s=document.querySelector('#mstatus').value,o=document.querySelector('#morigin').value;return rows.filter(r=>(!q||JSON.stringify(r).toLowerCase().includes(q))&&(!s||r.status===s)&&(!o||r.origin===o))}
function draw(){const list=filtered(),box=document.querySelector('#maintenance-content');if(view==='list'){box.innerHTML='<section class="panel"><h3>Acompanhamento</h3><div class="table-scroll"><table><thead><tr><th>Nº</th><th>Material / serviço</th><th>Origem</th><th>Solicitante</th><th>Responsável</th><th>Status</th><th>Prazo</th><th>Pedido</th></tr></thead><tbody>'+list.map(r=>'<tr data-id="'+r.id+'"><td><strong>'+e(r.number)+'</strong></td><td>'+e(r.description)+'</td><td>'+e(r.origin)+'</td><td>'+e(r.requester)+'</td><td>'+e(r.buyer||'Não assumido')+'</td><td>'+e(r.status)+'</td><td>'+d(r.neededDate)+'</td><td>'+e(r.systemOrder||'—')+'</td></tr>').join('')+'</tbody></table></div></section>'}else box.innerHTML='<div class="maintenance-board">'+lanes.map(l=>{const a=list.filter(r=>l[1].includes(r.status));return '<section class="maintenance-lane"><header><strong>'+l[0]+'</strong><span>'+a.length+'</span></header><div>'+((a.length?a.map(card).join(''):'<p class="maintenance-empty">Nenhuma solicitação</p>'))+'</div></section>'}).join('')+'</div>';box.querySelectorAll('[data-id]').forEach(x=>x.onclick=y=>{if(!y.target.closest('select'))form(rows.find(r=>r.id===x.dataset.id))});box.querySelectorAll('[data-status]').forEach(s=>s.onchange=async()=>{const r=rows.find(x=>x.id===s.dataset.status),v={...r,status:s.value};delete v.history;delete v.createdAt;delete v.updatedAt;delete v.number;const z=await fetch('/api/maintenance',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(v)});if(!z.ok){alert((await z.json()).error);return}await load()})}
function form(r){document.querySelector('#me').innerHTML='<section class="panel maintenance-editor"><h3>'+(r.id?'Editar '+e(r.number):'Nova solicitação')+'</h3><form id="mf"><div class="maintenance-fields"><label>Tipo<select name="type">'+opt(['Material','Serviço'],r.type||'Material')+'</select></label><label>Origem<select name="origin">'+opt(['OC','WhatsApp','Outro'],r.origin||'WhatsApp')+'</select></label><label>Solicitante<input name="requester" required value="'+e(r.requester||'')+'"></label><label>Responsável pela compra<input name="buyer" value="'+e(r.buyer||'')+'"></label><label>OC<input name="oc" value="'+e(r.oc||'')+'"></label><label>Prioridade<select name="priority">'+opt(['Normal','Alta','Urgente'],r.priority||'Normal')+'</select></label><label>Equipamento / setor<input name="equipment" value="'+e(r.equipment||'')+'"></label><label>Quantidade<input name="quantity" value="'+e(r.quantity||'')+'"></label><label>UM<input name="unit" value="'+e(r.unit||'')+'"></label><label>Necessário até<input type="date" name="neededDate" value="'+e(r.neededDate||'')+'"></label><label>Status<select name="status">'+opt(sts,r.status||'Solicitado')+'</select></label><label>Fornecedor escolhido<input name="supplier" value="'+e(r.supplier||'')+'"></label><label>Pedido no sistema<input name="systemOrder" value="'+e(r.systemOrder||'')+'"></label><label>Entrega prometida<input type="date" name="promisedDate" value="'+e(r.promisedDate||'')+'"></label><label>Valor total (R$)<input name="amount" inputmode="decimal" placeholder="0,00" value="'+e(meta(r).amount||'')+'"></label><label>Condição de pagamento<input name="paymentTerms" placeholder="Ex.: Boleto 7 dias" value="'+e(meta(r).paymentTerms||'')+'"></label><label>Data do pedido<input type="date" name="orderDate" value="'+e(meta(r).orderDate||'')+'"></label><label>Execução prevista (serviço)<input type="date" name="serviceDate" value="'+e(meta(r).serviceDate||'')+'"></label></div><label>Material / serviço<textarea name="description" required>'+e(r.description||'')+'</textarea></label><div id="mw"></div><label>Observações<textarea name="notes">'+e(r.notes||'')+'</textarea></label><div class="maintenance-actions"><button>Salvar solicitação</button><button type="button" id="mc">Fechar</button></div></form></section>';const f=document.querySelector('#mf'),w=document.querySelector('#mw');const check=()=>{const terms=f.description.value.toLowerCase().split(' ').filter(x=>x.length>3),m=rows.filter(x=>x.id!==r.id&&!closed(x)&&terms.some(t=>x.description.toLowerCase().includes(t))).slice(0,3);w.innerHTML=m.length?'<div class="duplicate-warning"><strong>Possível solicitação duplicada</strong>'+m.map(x=>'<p>'+e(x.number)+' · '+e(x.description)+' · '+e(x.status)+' · '+e(x.buyer||'sem responsável')+'</p>').join('')+'</div>':''};f.description.oninput=check;check();document.querySelector('#mc').onclick=()=>document.querySelector('#me').innerHTML='';f.onsubmit=async x=>{x.preventDefault();const v=Object.fromEntries(new FormData(f));v.id=r.id;v.version=r.version;const oldQuotes=(()=>{try{return JSON.parse(r.quotesJson||'[]').filter(x=>x&&x.kind!=='commercial')}catch{return []}})();oldQuotes.unshift({kind:'commercial',amount:v.amount||'',paymentTerms:v.paymentTerms||'',orderDate:v.orderDate||'',serviceDate:v.serviceDate||''});delete v.amount;delete v.paymentTerms;delete v.orderDate;delete v.serviceDate;v.quotesJson=JSON.stringify(oldQuotes);const response=await fetch('/api/maintenance',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(v)}),j=await response.json();if(!response.ok){w.textContent=j.error;return}await load()}}
load();